pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 30.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr;

    // Smooth progress coupling: later in stream, punish residual waste more strongly
    score += 40.0 * norm_pr * (progress * progress);

    // Interaction of post_residual with mean residual: penalize when this bin's
    // leftover deviates from the fleet average (fragmentation indicator)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * pr / cap;

    // Lookahead coupling: reward when next item fits the post-residual smoothly,
    // penalize when it nearly fits (dead space creation)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - fit_gap * fit_gap);
        } else {
            let overflow = (nxt - pr) / cap;
            score += 20.0 * overflow * overflow;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across too many open bins early in the stream
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Slight reward for tight fits (post residual near zero) via smooth exponential
    score -= 20.0 * (-(pr / 20.0) * (-(pr / 20.0))).exp() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps that nothing can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // moderately awkward gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0) + (mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - 15.0 - pressure * 20.0;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // fresh bin useful for the upcoming large item
        }
    }

    // Lookahead: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bin pressure: mildly discourage proliferation of bins.
    score += open_bins_count as f64 * 0.3;

    // Late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Prefer filling bins below mean residual (denser bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

