pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves further slack: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 2.0;
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += 60.0;
        }
    }

    // Penalize unusable dead space (residual too small for any plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer bins tighter than the current mean residual (good fits first).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for opening new bins early in the stream when current
    // fit is poor; late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it's chosen only for poor fits.
        score += 90.0 - 80.0 * progress;
    }

    // Mildly discourage fragmenting many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap; // fraction of bin used after placement

    // Base: reward tight packing (low post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Smooth polynomial coupling: tight fits become progressively more valuable
    // as the stream advances (quadratic in progress).
    score -= 25.0 * fill * fill * (progress * progress * (2.0 - progress));

    // Penalize dead space that is too small to be useful later (smooth trough).
    let dead = post / cap;
    score += 12.0 * (dead * (1.0 - dead)).powi(2) * 4.0; // peaks when post ~ 50, zero at 0 and cap

    // Lookahead: reward if next item fits exactly in the post residual (smooth).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0) * gap / cap * 10.0; // smooth proximity reward
        score += 8.0 * gap / cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one is far from mean residual.
    score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).sqrt();

    // New-bin candidate: keep it neutral-to-slightly-worse unless residuals are large.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

