pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with non-linear shaping
    let mut score = x * (1.0 + 0.5 * x * x);

    // Smooth coupling: as stream progresses, prefer tighter fits more strongly
    score *= 1.0 + 0.8 * progress * (1.0 - x);

    // Reward near-perfect fits via smooth valley around x = 0
    score -= 0.6 * (-x * x / 0.02).exp();

    // Dead-space penalty: residual too small for any plausible item (10..80 -> here 1..100)
    let min_item = 1.0f64;
    let unusable = ((min_item - x * cap).max(0.0)) / cap;
    score += 2.0 * unusable * unusable;

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (x * cap - n) / cap;
        score -= 0.4 * (-(diff * diff) / 0.01).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Mild pressure against opening new bins when many are open with slack
    if bin_residual == bin_capacity {
        score += 0.3 + 0.2 * (open_bins_count as f64).ln().max(0.0) + mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (modulo arithmetic) ---
    // Residuals in "harmonic" classes (multiples of common item sizes 10..80)
    // are more reusable. Penalize residuals that fall in dead zones.
    let r = post_residual;
    let harmonic_bonus: f64 = if r == 0 {
        -30.0 // perfect fit: strong reward
    } else {
        match r % 10 {
            0 => -8.0,               // clean multiple of 10: reusable
            5 => 3.0,                // half class: mildly awkward
            _ => {
                // dead-space penalty grows for small awkward remainders
                let frac = (r % 10) as f64 / 10.0;
                6.0 * (1.0 - frac)
            }
        }
    };
    score += harmonic_bonus;

    // --- Capacity-fraction thresholds on post_residual ---
    let c = bin_capacity as f64;
    let post_frac = r as f64 / c;
    // Residuals below ~10% capacity are near-dead space: penalize.
    if post_frac > 0.0 && post_frac < 0.10 {
        score += 12.0 * (0.10 - post_frac) / 0.10;
    }
    // Residuals in [0.10, 0.30) are "awkward zone" for mid-size items.
    else if post_frac < 0.30 {
        score += 4.0;
    }

    // --- Integer division threshold classes on next_item_size ---
    if next_item_size > 0 {
        let fits_next = next_item_size <= r;
        if fits_next {
            // Reward by lookahead size class (integer division thresholds)
            let class = next_item_size / 20; // 0..=5 harmonic class
            let reward = 10.0 + 4.0 * class as f64;
            // Extra reward if next item fills the bin exactly after this placement
            if next_item_size == r {
                score -= 25.0;
            } else {
                score -= reward;
            }
        } else {
            // Lookahead won't fit: penalize proportionally to wasted potential
            score += (next_item_size as f64 - r as f64).min(20.0);
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; opening a new bin is costly.
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score slightly above a perfect fit,
        // but attractive when open bins have poor fits.
        score = 55.0 - 2.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // --- Mean residual coupling: prefer bins near the mean (balanced packing) ---
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // --- Stream progression: early on, be conservative with new bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress); // discourage new bins early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (sizes >= 1, but small slivers are rarely usable) are heavily penalized.
    let dead_zone_max = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone_max {
        score += (dead_zone_max - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item still fits afterwards.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving a blocking gap.
        score += 6.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, it is
    // nearly full; prefer filling such bins.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.4;

    // New-bin candidate handling: an empty bin leaves a large residual; make it
    // attractive only when current bins would leave tiny dead space or none fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are already open
        // is NOT applied here; instead penalize slightly so tight fits win, but
        // relax when the item is large (would leave small residual anyway).
        let new_bin_cost = 25.0 - 0.15 * open_bins_count as f64;
        score += new_bin_cost;
        if item_size >= 60 {
            score -= 10.0; // large items: fresh bin often reasonable
        }
        if next_item_size > 0 && next_item_size > (bin_capacity - item_size) {
            score += 8.0; // next item won't fit here either; avoid chaining new bins
        }
    }

    score
}

