pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead coupling: penalize if post-residual is awkwardly small for next item
    // (next item can't reuse it), but reward if next item fits snugly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni as u32) <= post_residual {
            // next item fits: reward proportional to how well it fills leftover
            let next_fill = 1.0 - ((post_residual as f64 - ni) / bin_capacity as f64);
            score -= 10.0 * next_fill;
        } else {
            // leftover too small to be useful for the next item: dead space penalty
            let waste = post_residual as f64 / ni.max(1.0);
            score += 6.0 * waste.min(3.0);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // Penalize bins whose residual deviates far below the mean (fragmented outliers),
    // unless they fit perfectly.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Time horizon: later in the stream, consolidate more aggressively
    // (favor existing bins over opening new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tight;

    // New-bin candidate: make empty bin less attractive as open bins accumulate,
    // unless it's early or the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 10.0 * crowding * (0.5 + progress);
        // If the item barely fits anywhere and is large, opening fresh may be wise
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, modulated by a smooth polynomial in progress.
    // Early stream: prefer tight fills less aggressively (explore); late stream: strongly prefer small post_residual.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_weight;

    // Smooth quadratic penalty coupling post_residual with mean residual:
    // bins whose leftover deviates from the mean get penalized, favoring homogenization of residuals.
    let dev = pr_norm - mean_residual / cap;
    score += 40.0 * dev * dev * cap;

    // Smooth lookahead coupling: quadratic in how well next item could use the leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        let waste_frac = (post_residual - next_item_size) as f64 / cap;
        score -= 30.0 * (1.0 - waste_frac) * (1.0 - waste_frac) * (0.5 + progress);
    } else if next_item_size > post_residual {
        // Next item can't use the leftover: penalize proportionally to the squared leftover.
        score += 0.05 * pr * pr / cap;
    }

    // Last-chance bonus: smooth sigmoid-like term when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild preference for filling already-open bins vs opening new ones (smooth in open count).
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (10.0 + 8.0 * (open_bins_count as f64).sqrt());

    // Smooth reward for very tight fits (small post residual), quadratic in item/b residual ratio.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (mod-based dead-space taxonomy) ----
    // Classes of leftover space that are "reusable" for typical item sizes.
    let pr = post_residual;
    let mod_class = pr % 10;              // fine grain class
    let div_class = pr / 10;              // coarse decile class

    // Penalize leftovers that are awkward: small nonzero remainders (1..9)
    // are dead space; multiples of 10 align with common item granularities.
    if pr > 0 {
        if mod_class == 0 {
            score -= 6.0;                 // perfectly aligned leftover
        } else if mod_class <= 3 {
            score += (4 - mod_class) as f64 * 2.0; // nearly-dead slivers
        } else {
            score += mod_class as f64 * 0.4;       // mild mismatch penalty
        }
    }

    // Coarse decile reward: larger reusable chunks are good.
    score -= div_class as f64 * 1.5;

    // ---- Lookahead coupling: does next item fit the post-residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic check: does (pr % next) leave a clean class?
            let rem = pr % next_item_size;
            let fits_clean = (rem == 0) || (rem >= next_item_size / 2);
            score -= if fits_clean { 10.0 } else { 3.0 };
            // Bonus if next item would also leave an aligned class
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // This bin becomes dead after placement; penalize by the gap size.
            score += (next_item_size - pr) as f64 * 0.8;
        }
    }

    // ---- Last-chance pressure: only one bin fits -> avoid opening new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives; be pickier about bad fits.
        score += 2.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost + mild early-stream discount.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 25.0 * progress;
        // If current item is huge relative to capacity and would leave a
        // tiny residue elsewhere, opening fresh is attractive.
        if item_size as f64 > 0.6 * cap {
            score -= 8.0;
        }
        // If lookahead is also large, a fresh bin can host a clean pair.
        if next_item_size > 0 && (item_size + next_item_size) as u32 <= bin_capacity {
            score -= 15.0;
        }
        // Many open bins with high mean residual: reuse instead.
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.5;
        }
        return score;
    }

    // ---- Tight-fit reward: filling a bin nearly exactly ----
    if pr <= 5 && pr >= 0 {
        score -= 8.0;
    }

    // Prefer bins whose residual is below the mean (consolidating fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    // Late-stream consolidation: fewer open bins is better near the end.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.7 {
        score -= open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item (>=1) can use are worthless,
    // gaps too small for typical items (>=10) are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += 80.0; // unusable dead space (< minimum item size)
    } else if post_residual < 25 {
        score += 25.0; // risky small gap, likely dead
    } else if post_residual < 40 {
        score += 8.0;  // moderately usable gap
    } else {
        score -= 5.0;  // large flexible residual is valuable
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are already low.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0;
    }

    // Deviation from mean residual: prefer bins whose residual is already tight
    // (fill the fullest-fitting bins first, keep large residuals for future big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 30.0; // next item will perfectly consume the gap
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // gap will likely become dead space
    }

    // New-bin candidate: only attractive when residuals are large relative to the item
    // (i.e., no good fit exists) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 && avg_tightness < 0.35 {
            score += 70.0; // good fits exist elsewhere; don't open a new bin
        } else {
            score -= 20.0; // poor fits everywhere; fresh bin is fine
        }
    }

    // Progress coupling: later in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fits (low post_residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where the next item fits the new residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
            // Bonus for near-perfect 2-item packing.
            let two_gap = post_residual - next_item_size;
            if two_gap <= 5 {
                score -= 40.0;
            }
        } else {
            // Penalize leaving residual too small for the lookahead item (dead space).
            score += 30.0;
        }
    }

    // Compare residual to mean residual: prefer bins with tighter-than-average space usage.
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize slightly, but allow opening when remaining open
    // residuals are poor fits (high post_residual) and lookahead doesn't help.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && next_item_size > 0 && post_residual < next_item_size;
        score += if poor_fit { 25.0 } else { 120.0 };
    }

    // Early in the stream, keep bins tight to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a convex penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes the residual that could have been used elsewhere.
        // Penalize more when the item fits well in existing bins.
        let waste = bin_capacity as f64 - item_size as f64;
        score += 40.0 + 0.5 * waste;
        // Early in the stream, opening bins is cheaper (builds a portfolio); late, expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // Many open bins => opening another is more costly.
        score += 3.0 * open_bins_count as f64;
    } else {
        // Lookahead: reward if the next item can still fit into the post-residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward if next item fills the bin almost exactly.
            let after_next = post_residual as i64 - next_item_size as i64;
            if after_next <= 5 {
                score -= 6.0;
            }
        } else if next_item_size > 0 && post_residual < 10 {
            // Bin becomes dead space; slight penalty unless it was a near-perfect fit.
            if post_residual > 0 {
                score += 2.0;
            }
        }

        // Last-chance bonus: if this is the only bin that fits, strongly favor using it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }

        // Prefer bins whose residual deviates from the mean in a "usable" direction:
        // bins with larger-than-mean residual are better hosts for this item.
        score -= 0.3 * ((bin_residual as f64) - mean_residual);

        // Reward using bins that are already partially filled (fragment consolidation).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fill_ratio;
    }

    // Global pressure: when few bins fit the item anywhere, tighten selection generally.
    if fitting_bins_count <= 2 && !is_new_bin {
        score -= 4.0;
    }

    // Perfect fit override: leaving exactly zero residual is always excellent.
    if post_residual == 0 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic coupling of post_residual with stream progress.
    // Early stream: minimize post_residual (tight packing). Late stream: tolerate slack.
    let mut score = post * (1.0 + 0.6 * progress) - post * post / (2.0 * cap);

    // Reward near-perfect fits, smoothly via cubic decay of post_residual.
    score -= 12.0 * (1.0 - post / cap).powi(3);

    // Lookahead: bonus if next item fits smoothly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Penalize bins far below mean residual (fragmentation pressure), smoothly.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Mild pressure toward consolidation when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by small divisors is more reusable
    let pr = post_residual as i64;
    for &d in &[10u32, 20, 25, 50] {
        if pr > 0 && pr % d as i64 == 0 {
            score -= 8.0 + (d as f64) * 0.2;
        }
    }

    // Penalize dead space in "awkward" classes (small, hard-to-fill residues)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next-item coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a new bin only if it's early in the stream
    // or open bins are already tight; otherwise penalize new bins mildly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
        // opening new bin looks better if next item is large
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Tight bin preference: bins with small residual are precious, use them
    if bin_residual < 30 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean residual coupling: if this bin is much tighter than average, favor it
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Integer division threshold: post_residual in [10,20) is a good "half-class" leftover
    if post_residual >= 10 && post_residual < 20 {
        score -= 10.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use
    // are pure waste; tiny gaps (<10) are effectively dead.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Reward filling the majority of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize leaving gaps that can't fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // would force next item elsewhere / new bin
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // lookahead can still land here
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when item is large and would
    // otherwise create a poor fit; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 1.5 * open_bins_count as f64;
        score += base_penalty;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // large item deserves fresh bin
        }
    }

    // Mild stream-progress tilt: later, prefer tighter consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a post_residual that
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits here afterwards: reward tight match.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 80.0; // perfect 2-step packing
            }
        } else {
            // Next item will NOT fit in the leftover space: penalize
            // proportionally to how much dead space we create.
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Compare against mean residual: bins already tight are attractive targets.
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 5.0 * (1.0 - resid / mean_residual.max(1.0)).max(-1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and no good fit exists (large post_residual waste elsewhere).
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            1.0
        } else {
            0.0
        };
        score = bin_capacity as f64 + 30.0 - 55.0 * tightness
            + 0.3 * (item_size as f64);
        if next_item_size == 0 {
            score += 20.0; // near end of stream, prefer filling open bins
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 6.0;
        }
    }

    // Global state coupling: prefer using bins when many are open with high mean residual.
    if open_bins_count > 2 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }
    if mean_residual > 50.0 {
        score -= 5.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (favor tight fits there);
    // later, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive if the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.7 {
            score -= 20.0 * (fill - 0.7) / 0.3;
        } else {
            score += 15.0 * (0.7 - fill);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap; // fraction of bin used after placement

    // Base: reward tight packing (low post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Smooth polynomial coupling: tight fits become progressively more valuable
    // as the stream advances (quadratic in progress).
    score -= 25.0 * fill * fill * (progress * progress * (2.0 - progress));

    // Penalize dead space that is too small to be useful later (smooth trough).
    let dead = post / cap;
    score += 12.0 * (dead * (1.0 - dead)).powi(2) * 4.0; // peaks when post ~ 50, zero at 0 and cap

    // Lookahead: reward if next item fits exactly in the post residual (smooth).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0) * gap / cap * 10.0; // smooth proximity reward
        score += 8.0 * gap / cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one is far from mean residual.
    score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).sqrt();

    // New-bin candidate: keep it neutral-to-slightly-worse unless residuals are large.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the residual: quantize capacity into eighths.
    let eighth = bin_capacity as f64 / 8.0;
    let residual_class = (post_residual as f64 / eighth).floor();

    // Penalize residuals that fall into "dead" classes (too small for the
    // smallest plausible item, i.e. class 0 means post_residual < 12).
    if post_residual < 12 {
        score += 60.0;
    }

    // Reward residuals in harmonic classes divisible by common item sizes
    // (modular arithmetic on post_residual).
    if post_residual % 25 == 0 { score -= 8.0; }
    if post_residual % 20 == 0 { score -= 6.0; }
    if post_residual % 10 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 10.0; }

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // this is a chain of perfect fits — strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot use leftover space: penalize large leftovers.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // the item is large or many bins already exist and this bin would be a
    // tight fit elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted for large items.
        score += 30.0 - (item_size as f64 * 0.25);
        // If many bins are open, opening new bins fragments the state.
        score += (open_bins_count as f64) * 0.8;
        // Early in the stream, opening fresh bins is cheaper (long future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // Large items pair well with a fresh bin for the lookahead item.
        if next_item_size >= 50 { score -= 10.0; }
    } else {
        // Reward tightness relative to the mean residual of open bins:
        // prefer bins below the mean (they'll close out soon).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild bonus for very full bins (post_residual in top harmonic class).
    if residual_class <= 1.0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        // gap too small for typical items (size range 10..80): dead space
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // marginal gap: risky, mild penalty unless it fits the lookahead item
        score += 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    } else {
        // healthy residual: reward, especially if it can host the next item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 3.0; // next item won't fit here -> dead-space risk
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no good fit exists (mean residual is small).
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit {
            score += 25.0; // an open bin can take it -> don't open a new one
        } else {
            score -= 10.0; // nothing fits well -> fresh bin is reasonable
        }
        score += (item_size as f64 / bin_capacity as f64) * 5.0;
    }

    // Slight preference for bins below mean residual (balancing usage)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // Penalize dead space that next item cannot use (2-step lookahead).
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual as u32) as f64 * 0.8;
        } else {
            // Reward when next item fits snugly into the post residual.
            let gap = post_residual as u32 - next_item_size;
            score -= 0.6 * (1.0 - (gap as f64 / bin_capacity as f64));
        }
    }

    // Compare against mean residual: bins already below mean residual are better targets.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless residual would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) < item_size {
            score -= 20.0; // new bin pairs well with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual that cannot hold typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0;
        } else {
            // Next item won't chain; penalize proportionally to wasted chain potential.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer bins with less residual (best fit pressure).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: empty bin gets base cost plus pressure terms.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin; cheaper late in the stream or when open bins are full-ish.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        score += 15.0 + 10.0 * crowding - 8.0 * progress;
        // If next item is large, an empty bin is valuable for it.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Slight preference for filling bins that deviate above the mean residual
    // (balances residual distribution across open bins).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post_residual), with smooth polynomial shaping.
    let mut score = pr * pr / cap;

    // Smooth coupling: as the stream progresses, dead space becomes more costly.
    let progress_penalty = 1.0 + progress * progress * 2.0;
    score *= progress_penalty;

    // Reward bins whose post_residual matches the next item (lookahead fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = (pr - nxt).abs() / cap;
        score += match_term * match_term * (1.0 + progress);
        // Slight bonus if next item fits exactly-ish
        if pr >= nxt {
            score -= 2.0 * (1.0 - match_term);
        }
    }

    // Penalize last-chance bins less when fit is decent (avoid wasting a nearly-full bin).
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - pr / cap);
    }

    // Mild pressure toward consolidating bins: fewer open bins is better.
    score += 0.05 * (open_bins_count as f64) * (pr / cap);

    // Prefer bins with residual below the mean (fuller bins first).
    score += 0.3 * (pr - mean_residual).max(0.0) / cap;

    // New-bin candidate: only attractive when item is large or progress is late.
    if bin_residual == bin_capacity {
        let new_bin_bias = 0.4 * progress + 0.01 * item_size as f64;
        score += 3.0 - new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity octiles.
    let oct = (post_residual * 8 / bin_capacity.max(1)) as i64; // 0..8
    let octile_penalty: [f64; 9] = [0.0, 30.0, 22.0, 16.0, 12.0, 8.0, 5.0, 2.0, 0.0];
    score += octile_penalty[oct as usize];

    // Exact-fit / tiny leftover reward (dead-space avoidance).
    if post_residual == 0 { score -= 60.0; }
    else if post_residual <= 5 { score -= 25.0; }

    // Modulo-10 harmonic class: residuals near multiples of 10 pair well with
    // common item sizes (items often cluster on decade boundaries).
    let r10 = (post_residual % 10) as f64;
    score -= 4.0 * (5.0 - (r10 - 5.0).abs()) * 0.5; // prefer residuals close to decade multiples

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward for tight nesting of next item.
        let slack = post_residual - next_item_size;
        if slack <= 10 { score -= 10.0; }
    } else if next_item_size > 0 {
        // Dead-end for lookahead: penalize proportionally to next item size.
        score += (next_item_size as f64) * 0.35;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins
    // would create large dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_elsewhere = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else { 100.0 };
        // Prefer new bin if existing bins would waste a lot, or late in stream.
        score = 100.0 - dead_elsewhere * 0.8 - progress * 20.0
            + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 15.0; // next item won't fit here anyway; don't hoard
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

