        score -= 990.0;
    } else if post_residual <= 3 {
        score -= 240.0;
    } else if post_residual <= 8 {
        score -= 90.0;
    }

    // Tightness of the current placement (how much of the bin the item consumes).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 35.0 * tightness * tightness;

    // 2-step lookahead: chain placements with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 140.0 - slack * 2.5;
            if slack <= 4.0 {
                score -= 55.0;
            }
            if slack >= 10.0 && slack <= 60.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space.
            if post_residual >= 30 {
                score += 12.0;
            } else {
                score += 75.0;
            }
        }
    }

    // Penalize unusable dead space (residual too small for any plausible item).
    if post_residual > 0 && post_residual < 12 {
        score += 150.0 - 9.0 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 22 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer bins tighter than the current mean residual (good fits first).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Late-stream consolidation: mildly favor progress-aware tight fits.
    score -= 14.0 * progress * tightness;

    // Small residuals that the next item can't use: graded penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 46.0 - 1.2 * post_residual as f64;
    }

    // Reward residuals close to the running mean (predictable reuse).
    if post_residual > 0 && mean_residual > 0.0 {
        let near_mean = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
        score -= 6.0 * near_mean;
    }

    // Small gap right after next item fits: strong chain candidate.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap >= 1 && gap <= 5 {
            score -= 25.0;
        }
    }

    // New-bin candidate: baseline penalty so it's chosen only for poor fits,
    // with increasing reluctance as the stream progresses.
    if bin_residual == bin_capacity {
        score += 90.0 - 80.0 * progress;
        if progress > 0.5 && fitting_bins_count > 0 {
            score += 25.0 * progress;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 40.0 * progress;
        }
    }

    // Mildly discourage fragmenting many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

