pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        // Dead space severity: the smaller the gap, the more useless it is.
        let gap = post_residual as f64;
        let dead_penalty = 40.0 * (1.0 - gap / bin_capacity as f64);
        score += dead_penalty;

        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward using the bin when it is the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering into many open bins when
    // residuals are already fragmented; encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Prefer bins with residual close to mean residual (balanced packing),
    // slightly penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: neutral-ish baseline; only attractive when the item
    // is large relative to typical residuals (avoid cramming big items).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // penalize gap between what remains and what the next item needs
        let gap = (post_residual - next_item_size) as f64;
        score += gap * 0.5;
        // bonus if next item still fits after this placement
        score -= 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare post_residual against mean residual: avoid creating outliers of waste
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - pr) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when fitting bins exist, especially early/mid stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing similar items in a fresh bin is attractive
            score -= 20.0;
        }
    }

    // Prefer tighter fits generally
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimizing post residual (tight fit), but dampen so
    // exact fits don't blindly dominate over strategic considerations.
    let mut score = post * (1.0 + 0.5 * t);

    // Reward tight fits strongly (small post_residual relative to item size).
    let tightness = if item_size > 0 { post / item_size as f64 } else { 1.0 };
    score += tightness * 10.0;

    // Penalize leaving dead space that no typical future item can use:
    // small post_residual that is not zero is wasteful only if very small;
    // large post_residual is still reusable. Penalize the "awkward zone".
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // chain fit quality: prefer when next item nearly fills remainder
            score -= 30.0 * (nxt / post.max(1.0));
        } else {
            // next item won't fit here; slight penalty scaled by how much it misses
            let miss = (nxt - post) / cap;
            score += 15.0 * miss;
        }
        // If this bin would be emptied perfectly and next item is large,
        // that's fine (bin closes). No extra penalty.
    } else {
        // Last item: pure tightness matters most.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many alternatives: be pickier about this bin (mild penalty encourages
    // choosing the genuinely best fit among several).
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: if mean residual is high (bins are loose),
    // prefer filling existing bins more aggressively.
    let mean_frac = mean_residual / cap;
    score -= 20.0 * mean_frac * fit_frac;

    // New-bin candidate handling: bin_residual == bin_capacity means this is
    // the empty-bin candidate. Its post_residual = cap - item_size. Make it
    // attractive only when no open bin fits well (few fitting bins) or when
    // the item is large relative to capacity.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Large items justify new bins more (less likely to fit elsewhere well).
        score -= 40.0 * fit_frac;
        // If other bins can fit the item, opening a new bin is usually worse.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 30.0 * (1.0 - t);
        // If next item is large, a fresh bin may serve it after this one.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 20.0;
        }
    }

    // Mild preference for keeping bin count stable mid-stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex to prefer tight fits
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, keep residuals flexible (penalize small residuals less),
    // late, prefer tight packing strongly.
    let tightness = 1.0 - norm_pr; // how full the bin becomes
    let coupling = (progress - 0.5) * (progress - 0.5) * 4.0; // 0 at start, 1 at end
    score -= 40.0 * coupling * tightness * tightness * tightness;

    // Smooth interaction: residual vs mean residual deviation, scaled by progress
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * (1.0 - progress) * dev * dev * cap;

    // Dead-space penalty: residual too small to fit typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            // reward leaving room exactly for next item (smooth bump)
            let x = (pr - nx) / cap;
            score -= 10.0 * (-x * x * 20.0).exp();
        }
    } else {
        // last item: strongly prefer zero residual
        score += 8.0 * norm_pr;
    }

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize lightly early, more when many bins open poorly fit
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 3.0 * (1.0 - progress);
    }

    // Mild penalty for too many open bins
    score += (open_bins_count as f64) * (1.0 - progress) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit reward: post_residual in tiny residue classes gets big bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes (10,20,25,50)
    // remain reusable; odd residuals are dead space.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable {
        score -= 40.0;
    } else {
        score += 25.0;
    }

    // Integer-division threshold: residual below the minimum item size is dead space.
    if post_residual < 10 {
        score += 200.0;
    }

    // Lookahead coupling: can next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0;
            // Harmonic match: next item exactly fills remaining space
            if next_item_size == post_residual {
                score -= 120.0;
            }
        } else {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin when existing residuals are small and unusable
        score += 250.0 - 200.0 * (1.0 - fragmentation) - 100.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 20.0;
        }
    }

    // Mild pressure toward filling fuller bins (smaller post_residual) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += frac * 50.0 * progress;

    // Prefer bins with residual close to item (tight fit) via harmonic distance.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Penalize spreading across many open bins slightly; reward consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Strict dead-space penalty: residuals that are too small for any
    // plausible future item (1..=10 unusable, 11..=30 mostly unusable).
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // total dead space
        } else if post_residual <= 30 {
            score += 30.0 * (1.0 - post / 30.0);
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the current item is large
    // (would leave a big hole in an existing bin) or many bins are open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 20.0).min(1.0);
        let large_item = (item / 100.0).powi(2);
        score = cap - post + 55.0 - 30.0 * pressure - 45.0 * large_item;
        // If the next item could pair with the leftover, opening a new bin
        // is less attractive.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this bin.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 35.0;
    }

    // Mild pressure to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins below mean residual (balance load).
    score += 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
