pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack * 0.8; // chainable, reward decays with slack
        } else {
            // Next item won't fit here: penalize leftover dead space proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to typical residuals or current bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = bin_capacity as f64 - mean_residual;
        // Reward new bin when open bins are crowded or item is big.
        let crowding = (avg_fill / bin_capacity as f64).clamp(0.0, 1.0);
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score -= 150.0 * crowding * (0.5 + size_pressure) * (0.5 + 0.5 * progress);
        // Penalize hoarding bins early in the stream.
        score += 40.0 * (1.0 - progress);
        // Never open a new bin if an open bin fits the item perfectly.
        if next_item_size > 0 && item_size == bin_residual {
            score += 500.0;
        }
    }

    // Mild tie-break: prefer filling bins with lower mean residual (denser bins).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Penalize post-residuals that are dead space: too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item could fit into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit anywhere after this placement, mild penalty for waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 55.0;
        // More attractive early in the stream (future flexibility worth more).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        // Attractive when few bins can fit the item (poor alternatives).
        score += (fitting_bins_count as f64) * 12.0;
        // Discourage opening when the mean residual across open bins is already large.
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // Discourage when many bins are open (fragmentation risk).
        score += (open_bins_count as f64).sqrt() * 3.0;
    } else {
        // Prefer reusing bins that are already partially filled: keep many
        // moderately-filled bins rather than many nearly-empty ones.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Late in the stream, consolidation matters more: penalize leaving scattered residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // Slight preference for bins whose residual deviates from mean (balance exploitation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
