pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let x = post / capacity; // normalized post residual in [0,1]

    // Base: reward tight fits via non-linear decay of post residual
    let mut score = post;

    // Smooth polynomial coupling with stream progress:
    // early in the stream, small residuals are less critical; later, waste compounds.
    let coupling = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * coupling;

    // Smooth interaction: penalize moderate waste more when few bins fit (scarcity)
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score += 15.0 * x * scarcity * (0.5 + progress);

    // Reward bins whose residual stays usable for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / capacity;
        let usable = 1.0 - ((post - next_item_size as f64) / capacity).abs();
        let bonus = (usable * (1.0 - nx)).max(0.0);
        score -= 12.0 * bonus * (1.0 - progress * 0.5);
    }

    // Slight preference toward consolidating into already-open bins vs new bin,
    // smoothly modulated by mean residual alignment
    let alignment = 1.0 - (x - mean_residual / capacity).abs();
    score -= 5.0 * alignment.max(0.0);

    // Last-chance bonus: if this is the only fitting bin, encourage using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover belongs to a
    // "usable" class (multiples of small divisors of capacity) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Class 1: post_residual divisible by 10 -> leftover likely reusable
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // Class 2: divisible by 5 but not 10 -> mildly reusable
        else if pr % 5 == 0 {
            score -= 2.5;
        }
        // Class 3: small dead space (< 10) -> heavily penalize
        if pr < 10 {
            score += 18.0;
        } else if pr < 20 {
            score += 6.0;
        }
    } else {
        // Perfect fill: best possible outcome
        score -= 25.0;
    }

    // Integer-division threshold coupling: does the NEXT item fit into the
    // post residual? If yes, reward strongly (chained packing).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // Extra harmonic reward: next item leaves another clean class
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += 3.0;
            if next_item_size > bin_residual {
                score += 4.0; // next item won't fit here at all; leftover is pure waste
            }
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit is bad (large post residual) or when
    // the next item is large and would benefit from fresh capacity.
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64; // = 0 for a fresh bin
        score += 4.0; // mild default cost of opening a new bin
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 6.0; // big next item: fresh bin is valuable
        }
        if fitting_bins_count == 1 {
            score += 30.0; // never open new bin when an open bin is the only fit
        }
        if pr_existing_ok(post_residual, bin_residual) {
            // existing bins fit tightly; discourage new bin
            score += 5.0;
        }
    }

    // Progress-based mild pressure: later in the stream, prefer tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.5;

    // Prefer bins already below mean residual (tighter bins) slightly
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

// helper inline check: does an existing bin fit the item tightly (post <= 15)?
fn pr_existing_ok(post_residual: u32, _bin_residual: u32) -> bool {
    post_residual <= 15
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // gap of 1 -> +57, gap of 9 -> +33
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward very tight fits (post_residual small relative to item).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Penalize leaving a gap that the next item could not use anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it over wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins below average residual (fuller bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { -20.0 } else { 40.0 };
        score += pressure + (open_bins_count as f64) * 2.0;
        // Late in the stream, avoid opening bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 260.0;
    } else if post_residual <= 8 {
        score -= 95.0;
    }

    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 38.0 * tightness * tightness;

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 135.0 - slack * 3.0;
            if slack <= 4.0 {
                score -= 60.0;
            }
            if slack >= 10.0 && slack <= 60.0 {
                score -= 18.0;
            }
        } else {
            if post_residual >= 30 {
                score += 14.0;
            } else {
                score += 82.0;
            }
        }
    }

    if post_residual > 0 && post_residual < 12 {
        score += 155.0 - 9.0 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 22 {
        score += 9.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 48.0 - 1.2 * post_residual as f64;
    }

    if post_residual > 0 && mean_residual > 0.0 {
        let near_mean = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
        score -= 6.0 * near_mean;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap >= 1 && gap <= 5 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate gating: stricter late in the stream, so consolidation wins.
    if bin_residual == bin_capacity {
        score += 90.0 - 70.0 * progress;
        if progress > 0.5 && fitting_bins_count > 0 {
            score += 25.0 * progress;
        }
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 42.0 * progress;
        }
    }

    if open_bins_count > 10 && post_residual > 0 {
        score -= 3.0 * ((mean_residual - post_residual as f64).abs()).min(10.0);
    }

    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: the next item fits exactly into the leftover space (perfect 2-step chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Fits but with slack: reward proportional to tightness of the 2-step fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space creation.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Reward tight fits relative to the mean residual across open bins.
    let tightness = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless the fit is very tight.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced when item is large (good use of fresh space).
        score += 45.0 - 0.3 * item_size as f64;
        // Still allow a new bin if the 2-step chain is perfect in it.
        if next_item_size > 0 && next_item_size + item_size == bin_capacity {
            score -= 70.0;
        }
    }

    // Late in the stream: consolidate harder, avoid spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
