pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches 0
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't fit the smallest plausible item (1..100 unknown dist)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with smaller residual among fitting bins (best-fit flavor)
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    // Global state: many open bins -> discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But allow new bin if mean residual is low (open bins nearly full)
        score -= 0.5 * mean_residual;
    }

    // Mild mean-residual alignment: prefer bins close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Early on, keep bins flexible (penalize low post-residual mildly).
    // Later, tight fits (small post_residual) become valuable.
    let mut score = pr * (1.0 + 0.5 * (1.0 - progress) * norm_pr);

    // Non-linear reward for very tight fits, stronger as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that no typical item can use, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        let waste_frac = waste / cap;
        score += 20.0 * waste_frac * waste_frac * (1.0 + progress);
        // Reward bins whose post-residual matches the next item exactly.
        let match_term = 1.0 - (pr - nxt).abs() / cap;
        score -= 6.0 * match_term.max(0.0) * (0.3 + progress);
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild pressure to prefer fuller bins among many open bins.
    score += (open_bins_count as f64).ln() * norm_pr * 2.0;

    // Slight preference for bins with residuals near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize moderately so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
