pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more likely to be filled later.
    let pr = post_residual;
    let class = pr % 10; // decile of dead space
    let class_penalty: f64 = match class {
        0 => -6.0,          // perfect fill
        1..=3 => -3.0,      // near-perfect, tiny dead space
        4..=7 => 2.0,       // awkward mid residual
        _ => 5.0,           // large dead space (41..49 style gaps)
    };
    score += class_penalty;

    // Integer-division threshold: residual below half capacity is hard to reuse.
    if pr < bin_capacity / 2 {
        score += 4.0;
        if pr < bin_capacity / 4 {
            score += 3.0; // very small residual: nearly sealed bin, fine
            score -= 5.0;
        }
    } else {
        score -= 2.0; // residual above half stays reusable
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish: reward tight harmonic match
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 7.0;
            } else if gap <= 5 {
                score -= 4.0;
            } else {
                score -= 1.5;
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            let over = (next_item_size - pr) / 10;
            score += 2.0 + over as f64 * 1.5;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: keep it attractive only when current bins would leave
    // large dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > bin_capacity as f64 * 0.5;
        if big_item && (fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.6) {
            score -= 5.0 + 3.0 * (1.0 - progress);
        } else {
            score += 12.0; // discourage scattering into fresh bins
        }
    }

    // Congestion pressure: many open bins -> prefer consolidation into emptier ones.
    if open_bins_count > 4 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * spread;
    }

    // Modulo coupling on item size vs residual class (harmonic alignment).
    if (item_size % 10) == (bin_residual % 10) && bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min size 1, but practically tiny gaps) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0; // unusable sliver penalty
    }
    // Perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 10.0; // still potentially usable for tiny items
    }

    // Coupling with next item lookahead: bonus if residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but allow
    // opening a new bin when current fit is bad and alternatives are scarce.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: empty bin should only win when this bin's
    // fit creates dead space and it's the last fitting option.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0; // default penalty: prefer existing bins
        if fitting_bins_count <= 1 && post_residual < 10 {
            score -= 45.0; // open new bin rather than wreck last usable bin
        }
    } else if fitting_bins_count == 1 {
        score -= 15.0; // last-chance bin: use it to avoid opening a bin
    }

    // Mild phase awareness: tighter packing later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Prefer bins whose residual deviates favorably from the mean (tight bins).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is exponentially worse).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 45.0; // next item fills bin exactly: perfect 2-chain
        } else if gap <= 10 {
            score -= 25.0;
        } else if gap <= 25 {
            score -= 10.0;
        } else {
            // next item leaves a large unusable remainder -> penalize
            score += (gap as f64 - 25.0) * 0.15;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average (first-fit-like),
    // penalize bins much looser than average (avoid fragmenting large residuals).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins normally; discount penalty if residuals are large/wasted
        // or stream is early (more future items to fill the new bin).
        let mut penalty = 30.0;
        penalty -= fragmentation * 20.0;
        penalty -= late * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            penalty -= 40.0; // next item needs a fresh bin anyway
        }
        score += penalty.max(0.0);
    }

    // Mild tie-break: prefer filling more-open bins set (reduce bin count pressure).
    score += open_bins_count as f64 * 0.01;

    score
}

