    if post_residual == 0 { score -= 980.0 ; }
    else if post_residual <= 3 { score -= 260.0 ; }
    else if post_residual <= 8 { score -= 95.0 ; }

    let tightness = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 38.0 * tightness * tightness ;

    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 400.0 ; }
        else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 135.0 - slack * 3.0 ;
            if slack <= 4.0 { score -= 60.0 ; }
            if slack >= 10.0 && slack <= 60.0 { score -= 18.0 ; }
        } else {
            if post_residual >= 30 { score += 14.0 ; } else { score += 82.0 ; }
        }
    }

    if post_residual > 0 && post_residual < 12 { score += 155.0 - 9.0 * post_residual as f64 ; }
    else if post_residual >= 12 && post_residual < 22 { score += 9.0 ; }

    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= 15.0 * progress * tightness ;

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 48.0 - 1.2 * post_residual as f64 ;
    }

    // New-bin candidate: penalize opening a bin, but relax late when open bins
    // would leave large dead space (better to start fresh than strand capacity).
