        score -= 3.0 * (mean_residual - post_residual as f64) . abs () . min (10.0) ;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64 ;
        score += 2.0 * dead . max (1.0) . ln () * (1.0 - progress) * 12.0 ;
    }

