pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap;

    // Base: reward tight packing (low post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Strong exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 260.0;
    } else if post_residual <= 8 {
        score -= 95.0;
    }

    // Tightness coupling (item vs. available space).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 38.0 * tightness * tightness;

    // Lookahead: exact next-item fit is highly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 135.0 - slack * 3.0;
            if slack <= 4.0 {
                score -= 60.0;
            }
            if slack >= 10.0 && slack <= 60.0 {
                score -= 18.0;
            }
        } else {
            // Item won't leave a usable residue: penalize small residuals more.
            if post_residual >= 30 {
                score += 14.0;
            } else {
                score += 82.0;
            }
        }
    }

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 12 {
        score += 155.0 - 9.0 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 22 {
        score += 9.0;
    }

    // Progress-scaled tightness reward.
    score -= 15.0 * progress * tightness;

    // Smooth polynomial coupling: tight fits more valuable as stream advances.
    score -= 25.0 * fill * fill * (progress * progress * (2.0 - progress));

    // Lookahead smooth proximity reward.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0) * gap / cap * 10.0;
        score += 8.0 * gap / cap;
    }

    // Small residuals that cannot fit the next item are nearly dead (log-scaled, borrowed from best).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        if post_residual < 25 {
            score += 48.0 - 1.2 * post as f64;
        }
        score += 2.0 * (post as f64).max(1.0).ln() * (1.0 - progress) * 12.0;
    }

    // Near-mean residual bonus.
    if post_residual > 0 && mean_residual > 0.0 {
        let near_mean = 1.0 - ((post - mean_residual) / (mean_residual + 1.0)).abs().min(1.0);
        score -= 6.0 * near_mean;
    }

    // Small gap to next item is a good compaction signal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap >= 1 && gap <= 5 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: only allow when alternatives exist; tighter gating late in stream.
    if bin_residual == bin_capacity {
        if progress > 0.75 && fitting_bins_count > 1 {
            score += 55.0 * progress;
        } else if progress > 0.75 && fitting_bins_count > 0 {
            score += 42.0 * progress;
        } else if progress > 0.5 && fitting_bins_count > 0 {
            score += 25.0 * progress;
        } else {
            score += 5.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty when many bins are open and this one is far from mean residual.
    if open_bins_count > 10 && post_residual > 0 {
        score -= 3.0 * (mean_residual - post).abs().min(10.0);
    } else {
        score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual); late stream: allow looser fits
    // since residual space becomes less reusable as stream ends.
    let tightness = norm_pr * norm_pr; // quadratic penalty on large residuals
    let progress_shift = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += tightness * (1.0 - progress) * 30.0;
    score -= progress_shift * norm_pr * 10.0;

    // Cubic interaction: large residuals late in stream are less valuable.
    score += norm_pr.powi(3) * progress * 40.0;

    // Reward filling a bin nearly exactly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening new bins when open bins fit well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 - progress * 25.0;
        score += new_bin_penalty;
        // Lookahead: opening new bin is fine if next item is large.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt > item_size as f64 {
                score -= 15.0;
            }
        }
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Slight penalty for fragmenting when many bins are open.
    score += (open_bins_count as f64).sqrt() * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins near the mean to keep balance.
    score += (norm_pr * cap - mean_residual).abs() * 0.3 * (0.5 + progress);

    score
}

