    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    // Reward residuals that are highly divisible (many future items fit exactly).
    let mut div_count = 0u32;
    for d in [10u32, 20, 25, 40, 50] {
        if pr % d == 0 && pr > 0 {
            div_count += 1;
        }
    }
    score -= 3.0 * div_count as f64;

    // Penalize small dead zones: residuals in (0, 10) are nearly useless.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is excellent.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 30.0;
        } else if pr % next_item_size == 0 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space risk.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make it mildly attractive only when the item
    // is large relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are tight (low mean residual) and
        // item is big (poor fit anywhere).
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
