    // (favor filling existing bins); late, allow looser fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If item is huge relative to capacity, opening fresh is less bad.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If the only fitting bin is this new one, allow it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 30.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr;

    // Smooth progress coupling: later in stream, punish residual waste more strongly
    score += 40.0 * norm_pr * (progress * progress);

    // Interaction of post_residual with mean residual: penalize when this bin's
    // leftover deviates from the fleet average (fragmentation indicator)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * pr / cap;

    // Lookahead coupling: reward when next item fits the post-residual smoothly,
    // penalize when it nearly fits (dead space creation)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - fit_gap * fit_gap);
        } else {
            let overflow = (nxt - pr) / cap;
            score += 20.0 * overflow * overflow;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across too many open bins early in the stream
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Slight reward for tight fits (post residual near zero) via smooth exponential
    score -= 20.0 * (-(pr / 20.0) * (-(pr / 20.0))).exp() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap;

    // Base: reward tight packing (low post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Strong exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 260.0;
    } else if post_residual <= 8 {
        score -= 95.0;
    }

    // Tightness coupling (item vs. available space).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 38.0 * tightness * tightness;

    // Lookahead: exact next-item fit is highly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 135.0 - slack * 3.0;
            if slack <= 4.0 {
                score -= 60.0;
            }
            if slack >= 10.0 && slack <= 60.0 {
                score -= 18.0;
            }
        } else {
            // Item won't leave a usable residue: penalize small residuals more.
            if post_residual >= 30 {
                score += 14.0;
            } else {
                score += 82.0;
            }
        }
    }

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 12 {
        score += 155.0 - 9.0 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 22 {
        score += 9.0;
    }

    // Progress-scaled tightness reward.
    score -= 15.0 * progress * tightness;

    // Smooth polynomial coupling: tight fits more valuable as stream advances.
    score -= 25.0 * fill * fill * (progress * progress * (2.0 - progress));

    // Lookahead smooth proximity reward.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0) * gap / cap * 10.0;
        score += 8.0 * gap / cap;
    }

    // Small residuals that cannot fit the next item are nearly dead (log-scaled).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        if post_residual < 25 {
            score += 48.0 - 1.2 * post;
        }
        score += 2.0 * post.max(1.0).ln() * (1.0 - progress) * 12.0;
    }

    // Near-mean residual bonus.
    if post_residual > 0 && mean_residual > 0.0 {
        let near_mean = 1.0 - ((post - mean_residual) / (mean_residual + 1.0)).abs().min(1.0);
        score -= 6.0 * near_mean;
    }

    // Small gap to next item is a good compaction signal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap >= 1 && gap <= 5 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: simplified, best-style gating — open a new bin only
    // when it can't be avoided (no fitting bins) or late in the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        } else if progress > 0.75 {
            score += 42.0 * progress;
        } else if progress > 0.5 {
            score += 25.0 * progress;
        } else {
            score += 60.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty when many bins are open and this one is far from mean residual.
    if open_bins_count > 10 && post_residual > 0 {
        score -= 3.0 * (mean_residual - post).abs().min(10.0);
    } else {
        score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer smallest post_residual (best fit), scaled.
    score += 0.5 * (post_residual as f64 / cap);

    // Harmonic class of post_residual: residues modulo 10 create "usable slot" classes.
    // Small residues (<10) are dead space -> penalize less if residue is exactly 0 (perfect fit).
    let residue_class = post_residual % 10;
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if residue_class == 0 {
        score -= 8.0;  // round residual keeps future modulo alignment
    } else if residue_class >= 5 {
        score -= 2.0;  // medium class, still usable for small items
    } else {
        score += 3.0;  // narrow dead-space class
    }

    // Integer-division thresholds on post_residual relative to typical small item sizes.
    let div_class = post_residual / 20; // 0..5 classes
    score -= div_class as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 6.0 - slack as f64 * 0.4;
        } else {
            // next item won't fit here; mildly penalize wasting a big residual bin
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let base_new = 12.0
            + (mean_residual / cap) * 10.0
            + (open_bins_count as f64).sqrt() * 2.0;
        // If item is small relative to capacity, opening a bin wastes space.
        score += base_new + (cap - item_size as f64) * 0.15;
        // But if no bin fits well (large post_residual elsewhere), new bin is fine.
        if post_residual == cap {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / cap) * 5.0;

    // Prefer bins below mean residual (keep residual distribution balanced).
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    // A gap is "dead" if it's too small to fit even the smallest plausible item (<= 12),
    // or too small for the lookahead item.
    if post_residual > 0 {
        if post_residual < 12 {
            score += 60.0;
        } else if next_item_size > 0 && post_residual < next_item_size as f64 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new bin has bin_residual == bin_capacity, so add pressure to its score).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0;
        // But if no existing bin fits well, new bin is fine: penalize existing bins
        // with large post_residual waste relative to item.
        score -= fitting_bins_count as f64 * 2.0;
    }

    // Lookahead coupling: reward if post_residual can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 10.0;
    }

    // Mild progression scaling: early in the stream, be slightly more conservative
    // about residual waste since many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does post_residual exactly match next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // two-step perfect chain
        } else if post_residual > next_item_size {
            // next item fits, reward tighter leftover after chain
            let chain_left = post_residual - next_item_size;
            score -= 50.0 - (chain_left as f64).min(50.0);
        } else {
            // next item won't fit here: penalize dead space relative to next item
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residual far from useful small-item sizes (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a new bin only when fit is poor
    if bin_residual == bin_capacity {
        score += 60.0 + post_residual as f64 * 0.2;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 200.0; // fresh bin chains perfectly with next item
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual nonlinearly.
    score += 0.8 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use the leftover.
        score += 8.0;
    }

    // Compare against mean residual: bins with residual far below mean
    // are "dying" bins; using them up is good.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 2.0 * (mean_residual - res_f);
    } else {
        score += 0.5 * (res_f - mean_residual);
    }

    // New-bin candidate logic: neutral-ish baseline; encourage opening a new
    // bin only when the item is large relative to capacity or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items late in stream; penalize otherwise.
        score = 25.0 + 20.0 * item_frac - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size <= post_residual && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0; // room for a big follower in fresh bin
        }
    }

    // Congestion: many open bins -> favor filling existing ones.
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped at early stages
    let mut score = pr * (0.8 + 0.4 * progress);

    // Smooth non-linear coupling: quadratic dead-space penalty grows with progress
    score += (norm_pr * norm_pr) * cap * (0.5 + 2.0 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr).powi(3) * 20.0 * (0.3 + progress);

    // Penalize large dead space relative to mean residual (fragmentation signal)
    score += ((pr - mean_residual).abs() / cap) * 10.0 * (1.0 - progress);

    // Last-chance bin bonus: prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress + 0.5);
    }

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across too many open bins early on
    score += (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * 5.0 * (1.0 - progress);

    // New-bin candidate handling: keep it neutral-to-slightly-worse unless residual is large
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress + norm_pr * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space quality.
    let pr = post_residual;
    if pr > 0 {
        // Class boundaries via integer division thresholds on capacity fractions.
        let quarter = bin_capacity / 4;   // 25
        let half = bin_capacity / 2;      // 50
        let eighth = bin_capacity / 8;    // 12
        if pr <= eighth {
            // Tiny sliver: nearly dead space, penalize unless it fits next item.
            score += 40.0;
        } else if pr <= quarter {
            score += 10.0;
        } else if pr <= half {
            score -= 5.0;
        } else {
            score -= 15.0;
        }
        // Modulo-arithmetic bonus: post_residual divisible by common item granules
        // (10) keeps space reusable by typical item sizes.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 5 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly or well in post space.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= bin_capacity / 8 {
                score -= 60.0;
            } else if slack <= bin_capacity / 4 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: this bin's leftover becomes dead space
            // until later; penalize small leftovers more (dead space risk).
            if pr > 0 && pr < bin_capacity / 4 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin for a single item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Mild exploration penalty early, stronger late (consolidate at end).
        let base = 30.0 + 60.0 * progress;
        // Penalize more if open bins have plenty of room (fragmentation low).
        let frag = (mean_residual - post_residual as f64).abs();
        score = base + frag * 0.2;
        if item_size >= bin_capacity / 2 && open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer tighter bins overall: closeness to mean residual signals balance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small preference for bins with residual close to item (tight fit).
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += tight * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
