pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny dead space: worst outcome, add strong penalty.
            score += 60.0 + (10 - post_residual) as f64 * 8.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // Large residual remains usable; mild reward scaled by size.
            score -= (post_residual - 35) as f64 * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward bins whose residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post-residual barely misses the next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (which adds a fresh bin to the count).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: discourage opening new bins when many are already open,
    // but encourage new bins when few exist (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 15.0 * (1.0 - progress.min(1.0));
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost grows with open bins.
        score += 10.0 + 3.0 * open_bins_count as f64 - new_bin_bonus;
        // New bin is attractive if no open bin fits well (all residuals small).
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly as stream progresses.
        score -= 2.0 * progress;
    }

    // Mild preference for tighter bins (small residual before placement).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * 0.5;
    score += 0.03 * bin_residual as f64 * 0.0; // neutralized coupling hook

    score
}

