pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.35 * next_item_size as f64;
        } else {
            score += 4.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
        // Perfect chain: item + next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize dead space that is too small to be useful (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward bins with residual below mean (compact them), penalize outliers.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early on, be selective (penalize loose fits); late, just fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
    score += (1.0 - progress) * 10.0 * (1.0 - tightness);

    // Many open bins: prefer consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += 18.0 - pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping.
    let mut score = post + (post * post) / cap + (post * post * post) / (cap * cap);

    // Tight fits are strongly rewarded (smooth coupling of item size with post residual).
    let fit_ratio = item_size as f64 / cap;
    score -= fit_ratio * (cap - post) * (1.0 - post / cap);

    // Stream progress coupling: early on, tolerate slack; later, demand tightness.
    let progress_coupling = progress * progress * (1.0 - progress);
    score -= progress_coupling * post * 2.0;
    score += progress * post * 0.5;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= next_item_size as f64 * (0.5 + progress);
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post) * 0.25;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Penalize bins far from the mean residual (avoid fragmentation outliers).
    score += (post - mean_residual).abs() * 0.15;

    // New-bin candidate: prefer it only when residuals are tight and progress is early.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.9 - 0.4 * progress) + cap * avg_tightness * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (0..=9 mod 10) are nearly sealed -> reward.
    let residue_class = post_residual % 10;
    let decade = post_residual / 10;

    // Reward tiny dead space strongly (perfect/near-perfect fits).
    if post_residual == 0 {
        score -= 40.0;
    } else if residue_class == 0 {
        score -= 12.0; // exact decade leftover, reusable by decade-sized items
    } else if residue_class <= 4 {
        score -= 6.0 - residue_class as f64;
    } else {
        // awkward leftovers (6..9 mod 10) are hard to fill: penalize
        score += (residue_class as f64 - 5.0) * 1.5;
    }

    // Deeper: leftover smaller than the minimum item size (<=10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item lands in same bin -> strong reward
            let slack = post_residual - next_item_size;
            score -= 10.0 + (10 - slack.min(10)) as f64;
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            let over_class = (next_item_size - post_residual) % 10;
            score += 2.0 + over_class as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (fresh empty bin): only attractive when current item
    // is large and would leave a clean harmonic class, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let clean_leftover = (bin_capacity - item_size) % 10 == 0;
        let mut bonus = 25.0 * (1.0 - progress);
        if clean_leftover { bonus += 8.0; }
        if item_size >= bin_capacity / 2 { bonus += 10.0; }
        // dampen when many bins already open
        bonus -= open_bins_count as f64 * 1.5;
        score -= bonus;
    } else {
        // Prefer filling existing bins slightly more when mean residual is high
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    // Mild preference for using bins with tight current residual (best-fit core).
    score += (bin_residual as f64 - post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // Small unusable-ish gaps slightly above the minimum item size.
    if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use this leftover -> dead space risk
        score += 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless
    // the fit is good; mild term scaled by tightness of fit.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += open_bins_count as f64 * (1.0 - tightness) * 8.0;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline neutral-ish score; opening a new bin wastes the mean
        // residual currently sitting in open bins.
        score = 50.0 + mean_residual * 0.5 + open_bins_count as f64 * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing next item with this one in a fresh bin
        }
        if fitting_bins_count == 1 {
            score += 120.0; // never open a new bin when a last-chance fit exists
        }
    }

    // Early stream: slightly favor consolidation to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap;

    // Base: reward tight packing (low post_residual), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Strong exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 980.0;
    } else if post_residual <= 3 {
        score -= 260.0;
    } else if post_residual <= 8 {
        score -= 95.0;
    }

    // Tightness coupling (item vs. available space).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 38.0 * tightness * tightness;

    // Lookahead: exact next-item fit is highly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 135.0 - slack * 3.0;
            if slack <= 4.0 {
                score -= 60.0;
            }
            if slack >= 10.0 && slack <= 60.0 {
                score -= 18.0;
            }
        } else {
            // Item won't leave a usable residue: penalize small residuals more.
            if post_residual >= 30 {
                score += 14.0;
            } else {
                score += 82.0;
            }
        }
    }

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 12 {
        score += 155.0 - 9.0 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 22 {
        score += 9.0;
    }

    // Progress-scaled tightness reward.
    score -= 15.0 * progress * tightness;

    // Smooth polynomial coupling: tight fits more valuable as stream advances.
    score -= 25.0 * fill * fill * (progress * progress * (2.0 - progress));

    // Lookahead smooth proximity reward.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 20.0) * gap / cap * 10.0;
        score += 8.0 * gap / cap;
    }

    // Small residuals that cannot fit the next item are nearly dead (log-scaled).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        if post_residual < 25 {
            score += 48.0 - 1.2 * post;
        }
        score += 2.0 * post.max(1.0).ln() * (1.0 - progress) * 12.0;
    }

    // Near-mean residual bonus.
    if post_residual > 0 && mean_residual > 0.0 {
        let near_mean = 1.0 - ((post - mean_residual) / (mean_residual + 1.0)).abs().min(1.0);
        score -= 6.0 * near_mean;
    }

    // Small gap to next item is a good compaction signal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap >= 1 && gap <= 5 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: simplified, tighter gating (borrowed from best heuristic).
    if bin_residual == bin_capacity {
        if progress > 0.75 && fitting_bins_count > 0 {
            score += 42.0 * progress;
        } else if progress > 0.5 && fitting_bins_count > 0 {
            score += 25.0 * progress;
        } else {
            score += 5.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty when many bins are open and this one is far from mean residual.
    if open_bins_count > 10 && post_residual > 0 {
        score -= 3.0 * (mean_residual - post).abs().min(10.0);
    } else {
        score += 0.05 * (post - mean_residual).abs() * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: reward small gaps between post_residual and next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (-gap / 12.0).exp();
    }

    // Penalize post_residual that is too small for the next item (dead space risk),
    // scaled by how close it is to being useless.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let rel_dead = dead / bin_capacity as f64;
        score += 25.0 * rel_dead * rel_dead;
    }

    // Penalize bins whose residual deviates from the mean (prefer balanced packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Base penalty keeps new bins from winning trivially.
        score += 10.0;
        // Reward opening fresh bins for large items (they leave useful residuals).
        score -= 35.0 * tightness;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // If the next item fits the post-residual of a fresh bin placement, boost new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tightness reward: strongly prefer bins where the item fills a large fraction.
    let fill_ratio = item / cap;
    score -= 18.0 * fill_ratio * (bin_residual as f64 / cap);

    // Penalize dead space: tiny post-residuals that nothing can use later.
    if post > 0.0 && post < 10.0 {
        score += 12.0 * (10.0 - post);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt).abs();
            score -= 25.0 / (1.0 + gap);
        } else {
            score += 4.0 * (nxt - post).min(20.0) / 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 25.0 * crowding - 8.0 * (1.0 - progress);
        if item as u32 > 60 {
            score -= 6.0; // big items justify fresh bins more readily
        }
    }

    // Mild penalty for scattering across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - 0.5).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth polynomial shaping
    let mut score = pr;
    score += 60.0 * norm_pr * norm_pr;

    // Early stream: tolerate loose fits; late stream: penalize waste more
    score -= 30.0 * norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * norm_pr * progress * progress;

    // Interaction: post_residual coupled with mean residual deviation
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 20.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 10.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mildly discouraged unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 15.0 * norm_pr;
    }

    // Crowding: many open bins -> favor consolidation
    score += (open_bins_count as f64).ln() * 3.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
