pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Harmonic class of post_residual: bins whose leftover falls into tight
    // classes are strongly preferred (small waste), mid classes penalized.
    let class = pr / 10;
    score += match class {
        0 => -8.0,
        1 => -3.0,
        2 => 0.0,
        3 => 2.0,
        4 => 4.0,
        _ => 6.0,
    };

    // Exact decile alignment bonus (modulo arithmetic on post_residual).
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 1.5;
    }

    // Lookahead: leftover must either fit the next item or be near-zero.
    if next_item_size > 0 {
        let n = next_item_size;
        if pr >= n {
            score -= 6.0;
            // extra reward if leftover is in a "harmonic" band around n
            if pr < n + 15 {
                score -= 2.0;
            }
        } else if pr > 0 {
            // dead space: cannot host next item -> penalize proportionally
            score += (n - pr) as f64 * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize unless the item is large or the resulting
    // residual beats the current mean residual of open bins.
    if bin_residual == bin_capacity {
        score += 14.0 - (item_size as f64) * 0.12;
        if (pr as f64) < mean_residual {
            score -= 4.0;
        }
        if next_item_size > 0 && pr >= next_item_size {
            score -= 2.0;
        }
    }

    // Progression coupling: later in the stream, prefer bins below the mean
    // residual (consolidation phase).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.5 * (mean_residual - pr as f64);

    // Slight penalty for leaving very awkward residuals (e.g. 1..9 range
    // that most items 10..80 can never use).
    if pr >= 1 && pr < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps that nothing can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // moderately awkward gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
