pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize residuals
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Penalize unusable dead space: residual below the minimum item size is pure waste
    if post_residual < 1 {
        score += 1000.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity, the better
    score -= (1.0 - fit_frac) * 30.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain placement)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let next_post = post - nxt;
            // Reward when next item also fits snugly
            score -= 25.0 * (1.0 - next_post / cap);
            // Extra bonus for perfect chain: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item can't use this leftover space; mild penalty proportional to wasted potential
            score += 8.0 * fit_frac;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Global state coupling: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than spreading
    let open_f = open_bins_count as f64;
    if mean_residual > (item_size as f64) {
        // Bins overall still have room; reward using this bin to reduce fragmentation
        score -= 5.0 * (mean_residual / cap);
    } else {
        // Open bins are nearly full; opening a new bin may be fine
        score += 3.0;
    }

    // Mild penalty on number of open bins to discourage needless spreading
    score += 0.15 * open_f;

    // Time horizon: early in the stream, be more conservative (penalize new bins);
    // late in the stream, tight packing matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later
        score += 20.0 * (1.0 - progress);
        // But if mean residual across bins is small, new bin is attractive
        score -= 15.0 * (1.0 - mean_residual / cap);
    } else {
        // Existing bin: reward usage more strongly as stream progresses
        score -= 10.0 * progress;
    }

    // Non-linear tightness reward: quadratic bonus for very small leftovers
    let tight = 1.0 - fit_frac;
    score -= 20.0 * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
