pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "useful" residue
    // classes (multiples of common item sizes / small dead space) get rewarded.
    let pr = post_residual;
    let dead = if pr == 0 { 0.0 } else if pr < 5 { -30.0 } else if pr < 10 { -15.0 } else { 0.0 };
    score += dead;

    // Modulo classes: leftover that is a multiple of 10 or 5 is more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Integer division thresholds on post_residual: small usable pockets vs large voids.
    let pocket = pr / 10; // number of 10-sized slots remaining
    score -= pocket as f64 * 2.5;

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
        } else {
            // next item cannot use this leftover: penalize proportionally to wasted class
            let waste_class = (pr / (next_item_size.max(1))) as f64;
            score += waste_class * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Capacity fraction coupling: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - pr) as f64 / cap;
    if fill_frac >= 0.5 {
        score -= fill_frac * 10.0;
    } else {
        score += (0.5 - fill_frac) * 8.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave
    // an awkward residue and next item is large.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline leftover of a fresh bin
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 8.0; // discourage fresh bin when pairing is possible elsewhere
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Stream progression: later in stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64).min(cap) * 0.05;

    // Mean residual context: when open bins are generally empty, avoid spreading.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 unknown distribution => assume ~10)
    // are "dead space". Penalize them quadratically.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 4.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Post residual cannot fit next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins => prefer consolidating into
    // already-open bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // New-bin candidate (empty bin): make it attractive only when the current
    // item fits poorly everywhere else. Base penalty keeps it from winning on
    // good fits; the penalty shrinks when mean residual is small (bins nearly
    // full) or when this bin would leave a large usable residual.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let mean_relief = (mean_residual / bin_capacity as f64) * 20.0;
        score += base_penalty - mean_relief;
        // If the item is large relative to capacity, opening a fresh bin is
        // more reasonable.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    } else {
        // Favor tighter bins: smaller bin_residual before placement is better
        // (best-fit flavor), scaled mildly.
        score += (bin_residual as f64) * 0.15;
        // Reward closeness of fit.
        score -= (1.0 - (item_size as f64 / bin_residual.max(1) as f64)) * 5.0;
    }

    // Small global calibration toward mean residual: bins far below mean
    // residual are less attractive (they are "fresher"), encouraging use of
    // fuller bins first.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

