    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits too: mild reward proportional to how well it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 50.0 - (slack_after_next as f64).min(50.0);
