    // but practically below typical small items): treat < 10 as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins whose post_residual is close to the mean
    // (balanced packing), penalize extreme outliers.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it moderately expensive so it's chosen only when
    // open bins give bad fits (their penalties dominate).
    if bin_residual == bin_capacity {
        score += 250.0 + (open_bins_count as f64) * 2.0;
    }

    // Early in the stream, be slightly more willing to open bins (build a diverse pool);
    // late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
