    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr * (1.0 + 1.5 * pr_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costly),
    // early on, leave room for future large items.
    let tightness = pr_norm * pr_norm * (3.0 - 2.0 * pr_norm); // smoothstep in [0,1]
    score += tightness * (20.0 + 40.0 * progress) - 15.0 * progress * pr_norm * (1.0 - pr_norm);

    // Reward leaving just enough room for the lookahead item (smooth Gaussian-like bump)
    if next > 0.0 {
        let gap = pr - next;
        let bump = (-gap * gap / 400.0).exp();
        score -= 12.0 * bump * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize bins far from the mean residual (prefer balanced residual pool)
    score += 0.3 * ((pr - mean_residual) / cap).powi(2) * 100.0 * (0.5 + 0.5 * progress);

    // Mild penalty for many open bins with large residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * pr_norm * (1.0 - progress);

    // New-bin candidate: neutral mid score; only chosen when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

