pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod 10 buckets) ---
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are multiples of 10 pair well with common item sizes
    match class {
        0 => score -= 12.0,           // perfectly harmonious residual
        5 => score -= 6.0,            // half-class, decent
        2 | 8 => score += 4.0,        // slightly awkward
        1 | 3 | 7 | 9 => score += 7.0, // odd-prime-ish dead space
        _ => score += 5.0,
    }

    // Integer-division thresholds on post_residual
    if pr == 0 {
        score -= 40.0; // perfect closure is ideal
    } else if pr < 10 {
        score += 15.0; // dead space below min item size is wasted forever
    } else if pr <= 20 {
        score += 3.0;  // small but usable
    }

    // Capacity fraction coupling: how full will the bin be
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill; // reward high fill non-linearly

    // Lookahead harmonic check: can next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // bonus if next item exactly harmonizes (residual consumed fully)
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
            // bonus if next item's own class matches residual class
            if pr % 10 == next_item_size % 10 {
                score -= 4.0;
            }
        } else {
            // next item cannot fit here; penalize large leftover less if tiny
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when current bin is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 55.0 - 15.0 * progress;
        // if many open bins with large mean residual, opening new bin is less attractive
        nb += mean_residual * 0.15;
        // if item is huge relative to capacity, new bin is more acceptable
        if item_size * 5 >= bin_capacity * 4 {
            nb -= 12.0;
        }
        // if next item is large too, a fresh bin gives flexibility
        if next_item_size >= bin_capacity / 2 {
            nb -= 8.0;
        }
        score = score.max(0.0) + nb;
    }

    // Mild tie-breaking by bin id proxy: prefer bins with residual close to mean
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver -> heavy penalty proportional to wasted capacity.
            score += 40.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 35 {
            score += 4.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item).
    score -= (item_size as f64) * 0.6;

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when mean residual is small or item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - item_size as f64).max(0.0);
        score += 30.0 - pressure * 1.5;
        // Late in the stream, opening fresh bins is riskier; penalize slightly.
        score += (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward leaving that gap; otherwise penalize gaps sized for nothing.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild preference for bins with below-average residual (keeps big gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that will accept the next item exactly
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        score -= 40.0 + (bin_capacity as f64 - next_post as f64) * 0.5;
        if next_post == 0 {
            score -= 150.0; // chained perfect fit
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize leaving awkward small residuals
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += dead * 0.6; // dead-space penalty scaled by lookahead
        }
    }

    // Prefer tight fits relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: avoid wasting the only fitting bin's space on small items
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if open_bins_count == 0 || (poor_fit && mean_residual < 30.0) {
            score -= 120.0;
        } else {
            score += 80.0; // discourage opening bins when reasonable fits exist
        }
    }

    score
}

