pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be conservative with tight fits;
    // late in the stream, strongly reward near-perfect fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill achieved by this placement.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward high fill ratio, more so later in the stream.
    score -= fill * (30.0 + 40.0 * progress);

    // Penalize small dead space non-linearly: residuals <= 10 are wasteful traps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // unless the dead space created is huge.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        score += post_residual as f64 * 0.3;
    }

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0 + 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving residual too small for the next item (dead space).
            let gap = post_residual as f64;
            if gap > 0.0 {
                score += gap * 0.25;
            }
        }
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than spreading.
    let mean_fill = mean_residual / bin_capacity as f64;
    if open_bins_count > 3 {
        score += mean_fill * 10.0;
        // Prefer bins whose residual is close to (but above) the mean residual:
        // balanced packing.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly:
        // i.e., the item would leave a very tight residual in any bin, or the
        // item is large and few bins fit it.
        let poor_fit_elsewhere = post_residual == 0 && fitting_bins_count <= 2;
        let large_item = item_size >= 70;
        if poor_fit_elsewhere || (large_item && fitting_bins_count <= 1) {
            score -= 20.0; // allow opening a fresh bin
        } else {
            score += 45.0 + 30.0 * (1.0 - progress); // discourage new bins, esp. early
        }
        // If the next item is small, an empty bin can host pairs nicely.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    // Mild time-horizon shaping: slightly flatten scores late in stream so
    // exact-fit signals dominate.
    score *= 1.0 - 0.15 * progress;

    score
}

