        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 3.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= reusable;

    // Penalize dead space: leftover smaller than the minimum item size is waste.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 40.0;
    }

    // Reward if next item fits into the post residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
