    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good fit (large post_residual elsewhere or many fitting bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
