    // Open-bin pressure: discourage scattering across many open bins when
    // mean residual is high; encourage filling bins with large residuals.
    if bin_residual > mean_residual {
        score -= 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score += 0.15 * (mean_residual - bin_residual as f64);
