        score -= 0.3 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight penalty for spreading across too many open bins.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

