    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: empty bin gets a base cost so we only open new bins
    // when existing fits are poor, but reward opening fresh bins when residuals
    // across open bins are highly fragmented.
    if bin_residual == bin_capacity {
