    }

    // Progress-based mild exploration: early in stream, keep bins tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // Prefer bins with below-mean residual (tighter bins fill faster)
    score += 0.3 * ((post_residual as f64) - mean_residual).max(-30.0).min(30.0);

    score
}

