        // If existing bins would leave big dead space, opening a fresh bin
        // becomes relatively better.
        score -= 0.45 * mean_residual;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits at all
        }
    } else {
        // Slight preference for reusing bins that are already "committed".
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fill_ratio;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post residual, with a smooth non-linear penalty on mid-range waste.
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: tolerate larger residuals; late stream: punish them harder.
    let w = 0.5 + 1.5 * progress; // smooth growing weight
    score += w * (x * (1.0 - x)) * cap * 0.6;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * cap * (0.3 + 0.7 * progress);

    // Penalize near-full bins slightly (dead space risk) unless residual is tiny.
    score += (x * x * x) * cap * 0.2;

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // Next item won't fit here: smooth penalty proportional to gap.
        score += ((next_item_size as f64) - pr) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild preference for bins below mean residual (consolidate waste) with smooth term.
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);

    // Slight bias against opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
