pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify residual into capacity-fraction bands.
    // Residuals in [0,10) are near-perfect fills -> strong reward.
    // Residuals in (10,20) are "dead" for most items (min size 1, but typical sizes larger).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect packing
    } else if pr < 10 {
        score -= 25.0; // nearly perfect: unusable sliver, effectively full
    } else if pr <= 20 {
        score += 15.0; // dead-zone: too small for typical items
    } else if pr <= 50 {
        score -= 5.0; // sweet spot: can host medium items
    } else {
        score += 8.0; // large residual left means we underfilled
    }

    // Integer-division thresholds: residual divisible classes
    // Residuals divisible by 10 align with common item sizes (decile harmony).
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 && pr % 10 != 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic class of the gap
            if gap < 10 {
                score -= 18.0;
            } else if gap <= 20 {
                score += 6.0;
            } else {
                score -= gap as f64 * 0.1;
            }
        } else {
            // next item cannot fit here; penalize leaving a mid-range residual
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and mean residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + 30.0 - progress * 10.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.35;
        // If many bins are open, prefer consolidating.
        score += open_bins_count as f64 * 1.5;
        // Exception: huge item next to a fresh bin is fine.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 25.0;
        }
    }

    // Mild preference for tighter existing bins when residuals are similar.
    score -= (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
