    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when many bins are open and it fits elsewhere
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 0 {
        score += 10.0 + (post_residual as f64) * 0.2;
    }

    // Late in stream, avoid wasting space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item uses leftover
            let use_frac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * use_frac;
        } else {
            // next item cannot use the leftover: mild penalty for large leftover
            score += 0.08 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize filling bins wastefully); late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post_residual as f64;
    score -= progress * 10.0 * tight;

    // Many open bins: encourage closing them out (prefer bins with small residual).
    let open_f = open_bins_count as f64;
    score += 0.02 * open_f * (bin_residual as f64 - mean_residual);

    // New-bin candidate adjustment: opening a new bin is penalized mildly,
    // unless the item fits poorly everywhere (handled via fitting_bins_count).
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_f;
        // but if this is the only fitting option, soften the penalty
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fit (low post residual), with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten packing later in the stream
    let prog_coupling = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0;
    score *= prog_coupling;

    // Reward near-full closures more aggressively as stream advances
    let fill = 1.0 - norm_pr;
    score -= 25.0 * fill.powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (nxt / cap);
        } else {
            score += 10.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // New-bin candidate: make it mildly unattractive early, more acceptable late
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    // Slight penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
