pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes of size 10 (capacity / 10)
    let class_width = (bin_capacity / 10).max(1);
    let post_class = post_residual / class_width;
    let post_mod = post_residual % class_width;

    // Reward small post_residual (tight fit)
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Penalize post_residuals that fall in "dead" classes: too small for typical items (1..100)
    // A residual below 10 is nearly dead space; a residual in a low class wastes capacity.
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0; // almost dead space
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Modulo coupling: residuals near class boundaries are awkward
    if post_mod < 3 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fits
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize large leftover if it's unusable for next
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they are poor
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // fewer open bins relative to stream progress -> new bin cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: placing into a bin far from mean residual is penalized
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Prefer bins whose residual is close to item_size (minimize slack)
    let slack = (bin_residual - item_size) as f64;
    score += slack * 0.1;

    // Integer-division threshold on item size: big items should go into tight bins
    if item_size > bin_capacity / 2 {
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals in [1, 10] are unusable
    // for typical items -> strong penalty; perfect fit gets big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score += 40.0; // dead gap: highly undesirable
    } else if post_residual <= 25 {
        score += 8.0; // mildly awkward gap
    } else {
        // Usable residual: reward proportionally to how well next item fits
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // leaves room for lookahead item
        }
    }

    // Tightness reward: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, mildly encourage filling existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: penalize slightly more when many bins open,
        // but allow opening when this bin's residual would be dead space.
        score += pressure * 4.0;
        if post_residual > 0 && post_residual <= 10 && next_item_size > post_residual {
            score -= 20.0; // existing bins would be wasted anyway
        }
    }

    // Mean-residual coupling: if this bin is far below average residual,
    // prefer filling it (consolidate space).
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // Late in stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward bins where the next item fits snugly into the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Perfect chain: next item exactly consumes the remainder
            if leftover_after_next == 0 {
                score -= 30.0;
            } else {
                // Reward proportional to how snugly next item fits
                let snugness = 1.0 - (leftover_after_next as f64 / post_residual as f64);
                score -= snugness * 15.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize dead space
            score += (post_residual as f64) * 0.3;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: only attractive when no open bin is decent
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward perfect fits (no dead space).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving residuals that are too small to ever be useful
    // (dead space: smaller than the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Post-residual can't hold next item: mild penalty, worse if residual
            // is large enough that we "wasted" space for nothing.
            if post_residual > next_item_size as f64 * 0.0 + 0.0 && post_residual < bin_capacity as f64 * 0.5 {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is costly; penalize it more when many bins are open
        // and mean residual is still large (existing bins have room).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 * 2.0;
        let mean_room = mean_residual / bin_capacity as f64;
        score += 60.0 + open_pressure * 3.0 + mean_room * 40.0 - progress * 15.0;

        // If the item is huge, a fresh bin is actually attractive (less fragmentation).
        if item_size > bin_capacity * 3 / 4 {
            score -= 40.0;
        }
        // If existing bins are nearly full on average, new bin is less bad.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Mild bonus for filling bins that are already mostly full.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 12.0 * fill_ratio;
    }

    // Penalize placements that leave residual far from any "useful" granularity:
    // prefer residuals near multiples of common item sizes.
    let r = post_residual as f64;
    let gran = (r / 10.0).round() * 10.0;
    score += (r - gran).abs() * 0.8;

    // Slight penalty for spreading across many bins when mean residual is high:
    // prefer consolidating into bins below mean residual (tighter bins).
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    // Time-horizon coupling: early in the stream, be conservative (favor balance);
    // late in the stream, squeeze hard (favor minimal post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

