pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 classes.
    let class = post_residual / (bin_capacity / 10).max(1);
    let mut class_penalty = match class {
        0 => -40.0,                       // perfect fill
        1 => -18.0,                       // tiny leftover, nearly perfect
        2 | 3 => -6.0,                    // usable for small items (10..30)
        4 | 5 => 2.0,                     // mid leftover, mediocre
        6 | 7 => 10.0,                    // awkward gap
        _ => 18.0,                        // large waste
    };
    score += class_penalty;

    // Dead space: residual too small for the minimum item size.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains where the next item also fits (tight coupling).
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize residuals that cannot host the next item.
            score += 8.0;
        }
    }

    // Exact modulo harmony: post_residual divisible by common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so we
    // only open a new bin when existing bins look truly bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + class_penalty * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing else fits reasonably: open new bin
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer reusing bins when many are open (bin-count pressure).
    score -= (open_bins_count as f64) * 0.3 * (1.0 - post_residual as f64 / bin_capacity as f64);

