            score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 + progress);
        } else {
            score += 5.0 * (1.0 - (gap / cap).powi(2)).max(0.0);
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score -= 0.3 * open_bins_count as f64 * (post / cap) * progress;

    // Mean-residual coupling: penalize deviating far from the average residual
    // (keeps residual distribution balanced, smooth quadratic term).
    score += 0.05 * (post - mean_residual).powi(2) / cap;

    // New-bin candidate handling: an empty bin has post == cap; discourage unless
    // no open bin fits well (high residual waste relative to mean).
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * (1.0 - progress) - 0.15 * mean_residual * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli
    let r = post_residual;
    let m3 = (r % 3) as f64;
    let m5 = (r % 5) as f64;
    let m10 = (r % 10) as f64;

    // Penalize post_residuals in "dead" harmonic classes: small nonzero
    // residues (1..=4) are nearly unusable for items >= 10.
    if r > 0 && r < 10 {
        score += 40.0;
    }
    score += (10 - (r % 10)) as f64 * 0.3;

    // Perfect-fit reward: post_residual divisible by 10 (harmonic class 0 mod 10)
    if r % 10 == 0 && r > 0 {
        score -= 8.0;
    }
    if r == 0 {
        score -= 30.0; // exact fill is ideal
    }

    // Integer-division thresholds: post_residual divided into item-size bands
    let band = r / 20; // 0..5
    score += band as f64 * 2.0; // prefer tighter bins (lower band => lower score)

    // Lookahead coupling: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 6.0;
            // harmonic match: next_item_size class matches residual class
            if r % 10 == next_item_size % 10 {
                score -= 4.0;
            }
            if r == next_item_size {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize by the overflow magnitude
            let over = (next_item_size - r) as f64;
            score += over * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild default score so it
    // wins only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 - (mean_residual * 0.1);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // slightly favor new bins when stream items are large
        }
    }

    // Stream progression: prefer tighter packing early, looser later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * m10 * 0.1;
    score += progress * m5 * 0.2;

    // Open-bin pressure: many open bins => discourage opening more / spreading
    score += open_bins_count as f64 * 0.15;
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 5.0; // creates a gap that likely can't host next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // prefer filling existing ones; when few are open, filling is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate.
        score += 20.0 + 6.0 * pressure;
        // Early in the stream a fresh bin is more acceptable.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.1 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, scaled by how many alternatives exist.
        score -= 4.0 + 2.0 * pressure;
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize tiny dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 40.0 * (over / 100.0);
        }
    }

    // Compare post_residual against mean residual: prefer bins left closer to the mean
    // (balanced residual distribution preserves flexibility).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to
    // what open bins would leave behind, or many bins are already open and fit is poor.
    if bin_residual == bin_capacity {
        let base = 120.0
            + 2.0 * open_bins_count as f64
            + 0.3 * (post_residual as f64);
        // If next item is huge, opening a fresh bin early is more attractive.
        let relief = if next_item_size >= 70 { 150.0 } else { 0.0 };
        score += base - relief;
    }

    // Slight stream-progression pressure: later in the stream, be more conservative
    // about leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
