    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins already fit well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, relaxed when many bins are open with
        // scattered residuals (fragmentation) or early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
