        if mean_residual > item_size as f64 + 20.0 {
            penalty += 5.0; // existing bins have plenty of room; don't open new
        }
        if fitting_bins_count == 0 {
            penalty -= 20.0; // nothing else fits: new bin is required
        }
        score += penalty.max(0.0);
    }

    // Mild preference for filling bins that are already heavily loaded
    // (consolidation reduces bin count variance).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 3.0;

    // Global fragmentation pressure: when mean residual is low, be extra careful
    // with large leftover gaps.
    if mean_residual < 15.0 && post_residual > 20 {
        score += 6.0;
    }

    score
}

