        score -= 1.5 + progress;
    }

    // Penalize bins whose residual deviates from the mean (keep residuals homogeneous),
    // so future items can fit multiple bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev.abs() * (1.0 + progress);

