            score -= 1.2 * (1.0 - slack).powi(2);
        } else {
            score += 0.4 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for opening new bins when many bins are already open late in stream.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are "usable" dead space; others are waste.
    let usable = if post_residual == 0 {
        2.0
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 {
        1.0
    } else if post_residual % 20 == 0 || post_residual % 10 == 0 {
        0.5
    } else {
        0.0
    };
    score -= usable * 8.0;

    // Fractional capacity fill: reward high fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r = post_residual - next_item_size;
        if r % 10 == 0 {
            score -= 15.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving awkward small gap
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly, but allow it when this bin would
    // leave a bad (non-harmonic) gap and mean residual is already low.
    if bin_residual == bin_capacity {
        let bad_gap = post_residual > 0 && post_residual % 10 != 0 && post_residual % 25 != 0;
        let _ = open_bins_count;
        if bad_gap {
            score -= 5.0 * (mean_residual / bin_capacity as f64);
        } else {
            score += 12.0;
        }
    }

    // Integer-division threshold: gaps in [1..=9] after placing are near-waste.
    if post_residual >= 1 && post_residual <= 9 {
        score += 15.0;
    }

    // Stream progression: late in stream, tighten up (prefer tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

