    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect fit is ideal
    }

    // Penalize leaving a gap that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 5.0; // gap remains usable for the next item
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 3.0;

    // Last-chance bonus: if this is the only bin that fits, favor it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 5.0;
        // allow new bin if item is large relative to residual pattern
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (bin_residual as f64 - item_size as f64 - post_residual as f64).abs() * 0.01;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

