    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain fit: this bin will be perfectly filled next step
        } else if next_item_size < post_residual {
            // next item fits here too: mild reward proportional to how tight the chain is
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 200.0 * tightness;
        } else {
            // next item cannot use the leftover: penalize dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Penalize small unusable residuals (dead space that few items can fill)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny slivers are almost useless
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Prefer bins with residual below mean residual (tighter packing first)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Prefer filling more-occupied bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.2 * (bin_capacity - bin_residual) as f64 * (1.0 - progress);

    // Mild penalty for opening new bins when several bins already fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 * (fitting_bins_count as f64).sqrt();
        // but allow new bin if open bins are crowded
        if open_bins_count > 8 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot use the post_residual space
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // dead space for next item; penalize proportionally
            score += 0.08 * post_residual as f64;
        } else {
            // next item fits in leftover: reward
            score -= 4.0;
            // extra reward if next item nearly fills leftover too
            let next_fill = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 3.0 * next_fill;
        }
    } else {
        // last item: strongly prefer filling bins as much as possible
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize so it is chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0;
        // opening new bin is more attractive late in the stream when many bins are open
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 5.0 * progress;
    }

    // Prefer bins with residual close to mean (balanced usage), avoid extreme outliers
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Prefer bins whose residual is just above item size (snug fit)
    let slack = (bin_residual - item_size) as f64;
    score += 0.02 * slack;

    // Slight preference to fill older/more crowded bins to consolidate
    score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = pr / cap;

    // Base: penalize post residual, with non-linear quadratic coupling
    let mut score = pr * (1.0 + 0.5 * fit_frac * fit_frac);

    // Stream progress coupling: dead space hurts more early (long future) 
    // but late in stream, tight fits matter more
    let tightness = 1.0 - (item_size as f64 / cap);
    score += 12.0 * fit_frac * fit_frac * (1.0 - progress) + 6.0 * fit_frac * progress;

    // Lookahead: reward if next item fits into post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        let kernel = (-fit_gap * fit_gap / (2.0 * 15.0 * 15.0)).exp();
        score -= 10.0 * kernel;
        // penalize if next item nearly exactly consumes residual leaving nothing
        score += 3.0 * (1.0 - (nx / cap).min(1.0)) * (1.0 - kernel);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure from number of open bins vs mean residual: prefer filling bins
    // with residual far from mean (keeps a spread of bin sizes)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 4.0 * dev * dev;

    // New-bin candidate: make empty bin moderately attractive only when residuals are bad
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score = cap * (1.0 + 0.8 * avg_waste * avg_waste) - 8.0 * progress;
    }

    score
}
